function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Blue sky
  brush.beginShape();
  brush.vertex(0, 0); // Top left
  brush.vertex(400, 0); // Top right
  brush.vertex(0, 400); // Bottom left
  brush.vertex(400, 400); // Bottom right
  brush.endShape(true);

  // Hills
  brush.fill("#98FB98", 255); // Light green hills
  brush.beginShape();
  brush.vertex(0, 200); // Top left hill
  brush.vertex(400, 200); // Top right hill
  brush.vertex(0, 300); // Bottom left hill
  brush.vertex(400, 300); // Bottom right hill
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255); // Yellow sun
  brush.beginShape();
  brush.vertex(150, 150); // Top of sun
  brush.vertex(250, 120); // Right of sun
  brush.vertex(350, 120); // Bottom of sun
  brush.vertex(250, 150); // Left of sun
  brush.endShape(true);
}
```

